definition:
CREATE OR REPLACE FUNCTION public.delete_journal_entries_on_source_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ids uuid[];
  v_source_table text := TG_ARGV[0];
BEGIN
  SELECT array_agg(id) INTO v_ids
  FROM journal_entries
  WHERE source_table = v_source_table AND source_id = OLD.id;

  IF v_ids IS NOT NULL THEN
    DELETE FROM journal_lines   WHERE journal_entry_id = ANY(v_ids);
    DELETE FROM journal_entries WHERE id               = ANY(v_ids);
  END IF;
  RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_journal_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_diff numeric;
    v_id   uuid;
BEGIN
    v_id := COALESCE(NEW.id, OLD.id);

    SELECT COALESCE(SUM(debit) - SUM(credit), 0)
      INTO v_diff
      FROM journal_lines
     WHERE journal_entry_id = v_id;

    -- Allow header-only inserts that haven't yet written lines (helper functions
    -- write lines after creating the header within the same transaction)
    IF NOT EXISTS (SELECT 1 FROM journal_lines WHERE journal_entry_id = v_id) THEN
        RETURN NEW;
    END IF;

    IF ABS(v_diff) > 0.005 THEN
        RAISE EXCEPTION
          'Journal entry % is unbalanced by %. Debits must equal credits.',
          v_id, v_diff;
    END IF;

    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.enforce_period_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_status text;
    v_period text;
    v_org    uuid;
BEGIN
    v_period := COALESCE(NEW.period, OLD.period);
    v_org    := COALESCE(NEW.organization_id, OLD.organization_id);

    SELECT status INTO v_status
      FROM public.accounting_periods
     WHERE organization_id = v_org AND period = v_period;

    IF v_status IS NULL OR v_status = 'open' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Reversal entries are allowed on closed (but not locked) periods for inserts/updates.
    IF TG_OP <> 'DELETE'
       AND v_status = 'closed'
       AND NEW.is_reversal_of IS NOT NULL THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION
      'Cannot write journal entry to period % (status=%). Reopen the period first.',
      v_period, v_status;
END
$function$

CREATE OR REPLACE FUNCTION public.enforce_subledger_completeness()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_requires_party     boolean;
    v_requires_allotment boolean;
    v_code               text;
BEGIN
    SELECT requires_party, requires_allotment, code
      INTO v_requires_party, v_requires_allotment, v_code
      FROM coa_accounts
     WHERE id = NEW.account_id;

    IF v_requires_party AND (NEW.party_kind IS NULL OR NEW.party_id IS NULL) THEN
        RAISE EXCEPTION
          'Account % (code %) requires party_kind + party_id on every posting',
          NEW.account_id, v_code;
    END IF;

    IF v_requires_allotment AND NEW.allotment_id IS NULL THEN
        RAISE EXCEPTION
          'Account % (code %) requires allotment_id on every posting',
          NEW.account_id, v_code;
    END IF;

    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.ensure_booking_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_property_id uuid;
  v_number jsonb;
BEGIN
  IF COALESCE(NEW.receipt_type, '') = 'booking'
     AND NULLIF(BTRIM(COALESCE(NEW.receipt_number, '')), '') IS NULL THEN
    SELECT ta.property_id
      INTO v_property_id
      FROM public.tenant_allotments ta
     WHERE ta.id = NEW.tenant_allotment_id;

    IF v_property_id IS NOT NULL THEN
      v_number := public.next_receipt_number(
        NEW.organization_id,
        v_property_id,
        COALESCE(NEW.payment_date, current_date)
      );
      NEW.receipt_number := v_number->>'receipt_number';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_deposit_transfer_before_onboarding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_je          journal_entries%ROWTYPE;
  v_onboarding  date;
  v_acct_code   text;
BEGIN
  SELECT je.* INTO v_je
  FROM journal_entries je
  WHERE je.id = NEW.journal_entry_id;

  IF v_je.source_table IS DISTINCT FROM 'manual' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(v_je.description, '') NOT ILIKE '%deposit transfer%' THEN
    RETURN NEW;
  END IF;

  SELECT ca.code INTO v_acct_code
  FROM coa_accounts ca
  WHERE ca.id = NEW.account_id;

  IF v_acct_code IS DISTINCT FROM '2100' OR COALESCE(NEW.credit, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.allotment_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ta.onboarding_date INTO v_onboarding
  FROM tenant_allotments ta
  WHERE ta.id = NEW.allotment_id;

  IF v_onboarding IS NOT NULL AND v_je.entry_date < v_onboarding THEN
    RAISE EXCEPTION
      'Deposit transfer entry_date (%) cannot be before allotment onboarding_date (%) for allotment %',
      v_je.entry_date, v_onboarding, NEW.allotment_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_owner_payment_journal_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bill_date date;
BEGIN
  IF NEW.source_table IS DISTINCT FROM 'owner_payments' OR NEW.source_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT bill_date
    INTO v_bill_date
    FROM owner_payments
   WHERE id = NEW.source_id;

  IF v_bill_date IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.entry_date := v_bill_date;
  NEW.period     := to_char(v_bill_date, 'YYYY-MM');

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_adjustment_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF COALESCE(NEW.is_deleted, FALSE) THEN RETURN NEW; END IF;
        v_lines := build_adjustment_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.adjustment_date, current_date),
                NEW.adjustment_type || ' — ' || COALESCE(NEW.reason, NEW.category),
                'tenant_adjustments', NEW.id, v_lines,
                jsonb_build_object('category', NEW.category,
                                   'reference_type', NEW.reference_type)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF COALESCE(NEW.is_deleted, FALSE) AND NOT COALESCE(OLD.is_deleted, FALSE) THEN
            v_existing_je := find_journal_entry_for_source('tenant_adjustments', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'adjustment soft-deleted');
            END IF;
            RETURN NEW;
        END IF;
        IF NOT COALESCE(NEW.is_deleted, FALSE) AND COALESCE(OLD.is_deleted, FALSE) THEN
            v_lines := build_adjustment_lines(NEW.id);
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.adjustment_date, current_date),
                'Adjustment re-posted',
                'tenant_adjustments', NEW.id, v_lines
            );
            RETURN NEW;
        END IF;
        IF NEW.amount IS DISTINCT FROM OLD.amount
           OR NEW.adjustment_type IS DISTINCT FROM OLD.adjustment_type
           OR NEW.category IS DISTINCT FROM OLD.category
        THEN
            v_existing_je := find_journal_entry_for_source('tenant_adjustments', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'adjustment changed');
            END IF;
            v_lines := build_adjustment_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 AND NOT COALESCE(NEW.is_deleted, FALSE) THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.adjustment_date, current_date),
                    'Adjustment corrected',
                    'tenant_adjustments', NEW.id, v_lines
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        -- trg_cascade_je_tenant_adjustments removes journal rows; do not reverse here.
        RETURN OLD;
    END IF;

    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_expense_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_lines := build_expense_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.expense_date, current_date),
                COALESCE(NEW.description, 'Expense'),
                'expenses', NEW.id, v_lines,
                jsonb_build_object('category_id', NEW.category_id,
                                   'subcategory_id', NEW.subcategory_id,
                                   'issue_type_id', NEW.issue_type_id,
                                   'data_source', NEW.data_source)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.amount IS DISTINCT FROM OLD.amount
           OR NEW.category_id IS DISTINCT FROM OLD.category_id
           OR NEW.subcategory_id IS DISTINCT FROM OLD.subcategory_id
           OR NEW.issue_type_id IS DISTINCT FROM OLD.issue_type_id
           OR NEW.expense_date IS DISTINCT FROM OLD.expense_date
           OR NEW.property_id IS DISTINCT FROM OLD.property_id
           OR NEW.apartment_id IS DISTINCT FROM OLD.apartment_id
           OR NEW.bed_id IS DISTINCT FROM OLD.bed_id
        THEN
            v_existing_je := find_journal_entry_for_source('expenses', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'expense changed');
            END IF;
            v_lines := build_expense_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.expense_date, current_date),
                    COALESCE(NEW.description, 'Expense (corrected)'),
                    'expenses', NEW.id, v_lines
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        v_existing_je := find_journal_entry_for_source('expenses', OLD.id);
        IF v_existing_je IS NOT NULL THEN
            PERFORM reverse_journal_entry(v_existing_je, 'expense deleted');
        END IF;
        RETURN OLD;
    END IF;

    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.trg_invoice_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
    v_inv_date    date;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF COALESCE(NEW.is_deleted, FALSE) THEN
            RETURN NEW;  -- don't post deleted-on-insert rows
        END IF;
        v_lines := build_invoice_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            v_inv_date := COALESCE(NEW.invoice_date,
                                   (NEW.billing_month || '-01')::date,
                                   NEW.created_at::date,
                                   current_date);
            PERFORM post_journal_entry(
                NEW.organization_id, v_inv_date,
                'Invoice ' || COALESCE(NEW.invoice_number, NEW.id::text),
                'invoices', NEW.id, v_lines,
                jsonb_build_object('invoice_type', NEW.invoice_type,
                                   'billing_month', NEW.billing_month)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        -- Soft-delete: reverse the existing entry
        IF COALESCE(NEW.is_deleted, FALSE) AND NOT COALESCE(OLD.is_deleted, FALSE) THEN
            v_existing_je := find_journal_entry_for_source('invoices', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'invoice soft-deleted');
            END IF;
            RETURN NEW;
        END IF;
        -- Un-delete (rare): re-post
        IF NOT COALESCE(NEW.is_deleted, FALSE) AND COALESCE(OLD.is_deleted, FALSE) THEN
            v_lines := build_invoice_lines(NEW.id);
            v_inv_date := COALESCE(NEW.invoice_date,
                                   (NEW.billing_month || '-01')::date,
                                   current_date);
            PERFORM post_journal_entry(
                NEW.organization_id, v_inv_date,
                'Invoice ' || COALESCE(NEW.invoice_number, NEW.id::text) || ' (re-posted)',
                'invoices', NEW.id, v_lines
            );
            RETURN NEW;
        END IF;
        -- Material edit: reverse and repost
        IF NEW.total_amount IS DISTINCT FROM OLD.total_amount
           OR NEW.rent_amount IS DISTINCT FROM OLD.rent_amount
           OR NEW.electricity_amount IS DISTINCT FROM OLD.electricity_amount
           OR NEW.other_charges IS DISTINCT FROM OLD.other_charges
           OR NEW.late_fee IS DISTINCT FROM OLD.late_fee
           OR NEW.invoice_type IS DISTINCT FROM OLD.invoice_type
        THEN
            v_existing_je := find_journal_entry_for_source('invoices', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'invoice amount changed');
            END IF;
            v_lines := build_invoice_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 AND NOT COALESCE(NEW.is_deleted, FALSE) THEN
                v_inv_date := COALESCE(NEW.invoice_date,
                                       (NEW.billing_month || '-01')::date,
                                       current_date);
                PERFORM post_journal_entry(
                    NEW.organization_id, v_inv_date,
                    'Invoice ' || COALESCE(NEW.invoice_number, NEW.id::text) || ' (corrected)',
                    'invoices', NEW.id, v_lines
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        v_existing_je := find_journal_entry_for_source('invoices', OLD.id);
        IF v_existing_je IS NOT NULL THEN
            PERFORM reverse_journal_entry(v_existing_je, 'invoice hard-deleted');
        END IF;
        RETURN OLD;
    END IF;

    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.trg_receipt_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
    v_ar_id       uuid;
    v_onb_inc_id  uuid;
    v_property_id uuid;
    v_apartment_id uuid;
    v_bed_id      uuid;
    v_amount      numeric;
    v_inc_lines   jsonb;
    v_receipt_label text;
    v_needs_repost boolean;
BEGIN
    -- ── Shared poster: reverse nothing, just post the receipt's journal(s) from
    --    the current NEW row. Used by INSERT and by the UPDATE repost path. ──
    -- (inlined below rather than a sub-function to keep this self-contained)

    IF TG_OP = 'INSERT' THEN
        IF COALESCE(NEW.is_deleted, FALSE) THEN RETURN NEW; END IF;

        v_receipt_label := 'Payment Received - ' || COALESCE(NULLIF(BTRIM(NEW.receipt_number), ''), NEW.id::text);
        v_lines := build_receipt_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.payment_date, current_date),
                v_receipt_label,
                'receipts', NEW.id, v_lines,
                jsonb_build_object('receipt_type', NEW.receipt_type,
                                   'payment_mode', NEW.payment_mode)
            );
        END IF;

        IF NEW.receipt_type = 'booking' AND NEW.tenant_allotment_id IS NOT NULL THEN
            v_amount     := COALESCE(NEW.amount_paid, 0);
            v_ar_id      := coa_id(NEW.organization_id, '1200');
            v_onb_inc_id := coa_id(NEW.organization_id, '4300');
            SELECT property_id, apartment_id, bed_id
              INTO v_property_id, v_apartment_id, v_bed_id
              FROM tenant_allotments WHERE id = NEW.tenant_allotment_id;

            v_inc_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id',   v_ar_id,
                    'debit',        v_amount,
                    'party_kind',   'tenant',
                    'party_id',     NEW.tenant_id,
                    'allotment_id', NEW.tenant_allotment_id,
                    'property_id',  v_property_id,
                    'apartment_id', v_apartment_id,
                    'bed_id',       v_bed_id,
                    'memo',         'Onboarding Charges Received'
                ),
                jsonb_build_object(
                    'account_id',   v_onb_inc_id,
                    'credit',       v_amount,
                    'property_id',  v_property_id,
                    'memo',         'Onboarding Charges Received'
                )
            );
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.payment_date, current_date),
                'Onboarding Charges Received',
                'receipts', NEW.id, v_inc_lines,
                jsonb_build_object('receipt_type', NEW.receipt_type, 'kind', 'onboarding_income')
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        -- 1) Soft-delete: reverse and stop (unchanged behaviour).
        IF COALESCE(NEW.is_deleted, FALSE) AND NOT COALESCE(OLD.is_deleted, FALSE) THEN
            FOR v_existing_je IN
                SELECT je.id FROM journal_entries je
                WHERE je.source_table='receipts' AND je.source_id=NEW.id
                  AND je.is_reversal_of IS NULL
                  AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id)
            LOOP
                PERFORM reverse_journal_entry(v_existing_je, 'receipt soft-deleted');
            END LOOP;
            RETURN NEW;
        END IF;

        -- 2) Live row: repost when a journal-affecting field changed, or when the
        --    row is being restored from soft-deleted.
        v_needs_repost :=
            NOT COALESCE(NEW.is_deleted, FALSE)
            AND (
                COALESCE(OLD.is_deleted, FALSE) = TRUE
                OR NEW.amount_paid       IS DISTINCT FROM OLD.amount_paid
                OR NEW.payment_date      IS DISTINCT FROM OLD.payment_date
                OR NEW.payment_mode      IS DISTINCT FROM OLD.payment_mode
                OR NEW.bank_account_id   IS DISTINCT FROM OLD.bank_account_id
                OR NEW.receipt_type      IS DISTINCT FROM OLD.receipt_type
                OR NEW.tenant_id         IS DISTINCT FROM OLD.tenant_id
                OR NEW.tenant_allotment_id IS DISTINCT FROM OLD.tenant_allotment_id
                OR NEW.receipt_number    IS DISTINCT FROM OLD.receipt_number
            );

        IF NOT v_needs_repost THEN
            RETURN NEW;
        END IF;

        -- Reverse the receipt's existing live journal entries...
        FOR v_existing_je IN
            SELECT je.id FROM journal_entries je
            WHERE je.source_table='receipts' AND je.source_id=NEW.id
              AND je.is_reversal_of IS NULL
              AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id)
        LOOP
            PERFORM reverse_journal_entry(v_existing_je, 'receipt edited — reposting');
        END LOOP;

        -- ...then re-post fresh from the new values (mirrors the INSERT path).
        v_receipt_label := 'Payment Received - ' || COALESCE(NULLIF(BTRIM(NEW.receipt_number), ''), NEW.id::text);
        v_lines := build_receipt_lines(NEW.id);
        IF jsonb_array_length(v_lines) > 0 THEN
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.payment_date, current_date),
                v_receipt_label,
                'receipts', NEW.id, v_lines,
                jsonb_build_object('receipt_type', NEW.receipt_type,
                                   'payment_mode', NEW.payment_mode)
            );
        END IF;

        IF NEW.receipt_type = 'booking' AND NEW.tenant_allotment_id IS NOT NULL THEN
            v_amount     := COALESCE(NEW.amount_paid, 0);
            v_ar_id      := coa_id(NEW.organization_id, '1200');
            v_onb_inc_id := coa_id(NEW.organization_id, '4300');
            SELECT property_id, apartment_id, bed_id
              INTO v_property_id, v_apartment_id, v_bed_id
              FROM tenant_allotments WHERE id = NEW.tenant_allotment_id;

            v_inc_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id',   v_ar_id,
                    'debit',        v_amount,
                    'party_kind',   'tenant',
                    'party_id',     NEW.tenant_id,
                    'allotment_id', NEW.tenant_allotment_id,
                    'property_id',  v_property_id,
                    'apartment_id', v_apartment_id,
                    'bed_id',       v_bed_id,
                    'memo',         'Onboarding Charges Received'
                ),
                jsonb_build_object(
                    'account_id',   v_onb_inc_id,
                    'credit',       v_amount,
                    'property_id',  v_property_id,
                    'memo',         'Onboarding Charges Received'
                )
            );
            PERFORM post_journal_entry(
                NEW.organization_id,
                COALESCE(NEW.payment_date, current_date),
                'Onboarding Charges Received',
                'receipts', NEW.id, v_inc_lines,
                jsonb_build_object('receipt_type', NEW.receipt_type, 'kind', 'onboarding_income')
            );
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        FOR v_existing_je IN
            SELECT je.id FROM journal_entries je
            WHERE je.source_table='receipts' AND je.source_id=OLD.id
              AND je.is_reversal_of IS NULL
              AND NOT EXISTS (SELECT 1 FROM journal_entries r WHERE r.is_reversal_of=je.id)
        LOOP
            PERFORM reverse_journal_entry(v_existing_je, 'receipt hard-deleted');
        END LOOP;
        RETURN OLD;
    END IF;
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_settlement_journal_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing_je uuid;
    v_lines       jsonb;
    v_should_post boolean;
    v_was_posted  boolean;
BEGIN
    v_should_post := COALESCE(NEW.status, '') IN ('completed', 'approved')
                     AND NOT COALESCE(NEW.is_deleted, FALSE);
    v_was_posted  := TG_OP = 'UPDATE'
                     AND COALESCE(OLD.status, '') IN ('completed', 'approved')
                     AND NOT COALESCE(OLD.is_deleted, FALSE);

    IF TG_OP = 'INSERT' THEN
        IF v_should_post THEN
            v_lines := build_settlement_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.settlement_date, current_date),
                    'Deposit settlement',
                    'deposit_settlements', NEW.id, v_lines,
                    jsonb_build_object('status', NEW.status)
                );
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        -- Status transition: not-posted → posted
        IF v_should_post AND NOT v_was_posted THEN
            v_lines := build_settlement_lines(NEW.id);
            IF jsonb_array_length(v_lines) > 0 THEN
                PERFORM post_journal_entry(
                    NEW.organization_id,
                    COALESCE(NEW.settlement_date, current_date),
                    'Deposit settlement',
                    'deposit_settlements', NEW.id, v_lines
                );
            END IF;
            RETURN NEW;
        END IF;
        -- Status transition: posted → not-posted (cancelled, soft-deleted, or rolled back)
        IF v_was_posted AND NOT v_should_post THEN
            v_existing_je := find_journal_entry_for_source('deposit_settlements', NEW.id);
            IF v_existing_je IS NOT NULL THEN
                PERFORM reverse_journal_entry(v_existing_je, 'settlement reverted');
            END IF;
            RETURN NEW;
        END IF;
        -- Both posted, but amounts changed → reverse and repost
        IF v_was_posted AND v_should_post THEN
            IF NEW.deposit_amount IS DISTINCT FROM OLD.deposit_amount
               OR NEW.pending_rent IS DISTINCT FROM OLD.pending_rent
               OR NEW.pending_eb IS DISTINCT FROM OLD.pending_eb
               OR NEW.pending_late_fees IS DISTINCT FROM OLD.pending_late_fees
               OR NEW.damages IS DISTINCT FROM OLD.damages
               OR NEW.other_deductions IS DISTINCT FROM OLD.other_deductions
               OR NEW.refund_amount IS DISTINCT FROM OLD.refund_amount
            THEN
                v_existing_je := find_journal_entry_for_source('deposit_settlements', NEW.id);
                IF v_existing_je IS NOT NULL THEN
                    PERFORM reverse_journal_entry(v_existing_je, 'settlement amounts changed');
                END IF;
                v_lines := build_settlement_lines(NEW.id);
                IF jsonb_array_length(v_lines) > 0 THEN
                    PERFORM post_journal_entry(
                        NEW.organization_id,
                        COALESCE(NEW.settlement_date, current_date),
                        'Deposit settlement (corrected)',
                        'deposit_settlements', NEW.id, v_lines
                    );
                END IF;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        v_existing_je := find_journal_entry_for_source('deposit_settlements', OLD.id);
        IF v_existing_je IS NOT NULL THEN
            PERFORM reverse_journal_entry(v_existing_je, 'settlement hard-deleted');
        END IF;
        RETURN OLD;
    END IF;

    RETURN NULL;
END $function$
